const input = $input.first().json;
const requiredFiles = ['MANIFEST.md', 'DEPENDENCY_MAP.md', 'VALIDATION_CHECKLIST.md', 'CHANGELOG.md', 'GATEKEEPER_HANDOFF.md', 'NEXT_ACTIONS.md'];
const packageFiles = Array.isArray(input.package_files) ? input.package_files : Array.isArray(input.files) ? input.files : [];
return [{
  json: {
    ...input,
    package_id: input.package_id || input.package_name || '',
    package_path: input.package_path || '',
    release_type: input.release_type || '',
    package_files: packageFiles,
    required_files: requiredFiles,
    blockers: [],
    warnings: [],
    parsed_manifest: null,
    parsed_dependency_map: null,
    registry_results: Array.isArray(input.registry_results) ? input.registry_results : [],
    validation_checklist: Array.isArray(input.validation_checklist) ? input.validation_checklist : [],
    package_status: 'PACKAGE_NEEDS_REVIEW'
  }
}];

const j = $input.first().json;
const missingFiles = j.required_files.filter((file) => !j.package_files.includes(file));
const blockers = [...j.blockers];
if (missingFiles.length) blockers.push(`MISSING_FILES:${missingFiles.join(',')}`);
if (!j.package_id) blockers.push('PACKAGE_ID_MISSING');
if (!j.package_path) blockers.push('PACKAGE_PATH_MISSING');
if (!j.release_type) blockers.push('RELEASE_TYPE_MISSING');
return [{
  json: {
    ...j,
    missing_files: missingFiles,
    blockers: Array.from(new Set(blockers)),
    required_files_status: missingFiles.length ? 'MISSING' : 'COMPLETE'
  }
}];

const j = $input.first().json;
const rawManifest = j.package_manifest ?? j.manifest ?? j.manifest_content ?? null;
const blockers = [...j.blockers];
let parsedManifest = null;
let manifestStatus = 'MISSING';
if (rawManifest) {
  try {
    parsedManifest = typeof rawManifest === 'string' ? JSON.parse(rawManifest) : rawManifest;
    manifestStatus = 'PARSED';
  } catch (error) {
    blockers.push('MANIFEST_PARSE_FAILED');
    manifestStatus = 'FAILED';
  }
} else {
  blockers.push('MANIFEST_MISSING');
}
return [{
  json: {
    ...j,
    parsed_manifest: parsedManifest,
    manifest_status: manifestStatus,
    blockers: Array.from(new Set(blockers))
  }
}];

const j = $input.first().json;
const rawDependencyMap = j.package_dependency_map ?? j.dependency_map ?? j.dependency_map_content ?? null;
const blockers = [...j.blockers];
let parsedDependencyMap = null;
let dependencyMapStatus = 'MISSING';
if (rawDependencyMap) {
  try {
    parsedDependencyMap = typeof rawDependencyMap === 'string' ? JSON.parse(rawDependencyMap) : rawDependencyMap;
    dependencyMapStatus = 'PARSED';
  } catch (error) {
    blockers.push('DEPENDENCY_MAP_PARSE_FAILED');
    dependencyMapStatus = 'FAILED';
  }
} else {
  blockers.push('DEPENDENCY_MAP_MISSING');
}
return [{
  json: {
    ...j,
    parsed_dependency_map: parsedDependencyMap,
    dependency_map_status: dependencyMapStatus,
    blockers: Array.from(new Set(blockers))
  }
}];

const j = $input.first().json;
const manifestArtifacts = Array.isArray(j.parsed_manifest?.artifacts) ? j.parsed_manifest.artifacts : [];
const dependencyArtifacts = Array.isArray(j.parsed_dependency_map?.artifacts) ? j.parsed_dependency_map.artifacts : [];
const registryResults = Array.isArray(j.registry_results) ? j.registry_results : [];
const blockers = [...j.blockers];
const unresolvedArtifacts = manifestArtifacts.filter((artifact) => {
  const id = artifact.artifact_id || artifact.artifact_key || artifact.id;
  return !registryResults.some((row) => row.artifact_id === id || row.artifact_key === id);
});
if (!registryResults.length) blockers.push('REGISTRY_LOOKUP_REQUIRED');
if (unresolvedArtifacts.length) blockers.push('UNRESOLVED_ARTIFACTS');
if (dependencyArtifacts.length && !j.parsed_dependency_map) blockers.push('DEPENDENCY_MAP_UNAVAILABLE');
return [{
  json: {
    ...j,
    manifest_artifacts: manifestArtifacts,
    dependency_artifacts: dependencyArtifacts,
    unresolved_artifacts: unresolvedArtifacts,
    registry_resolution_status: unresolvedArtifacts.length ? 'UNRESOLVED' : 'RESOLVED',
    blockers: Array.from(new Set(blockers))
  }
}];

const j = $input.first().json;
const manifestArtifacts = Array.isArray(j.manifest_artifacts) ? j.manifest_artifacts : [];
const registryResults = Array.isArray(j.registry_results) ? j.registry_results : [];
const shaMismatches = [];
for (const artifact of manifestArtifacts) {
  const id = artifact.artifact_id || artifact.artifact_key || artifact.id;
  const expectedSha = artifact.sha256 || artifact.content_sha256 || artifact.contentSha256;
  if (!id || !expectedSha) continue;
  const registryRow = registryResults.find((row) => row.artifact_id === id || row.artifact_key === id);
  const actualSha = registryRow?.sha256 || registryRow?.content_sha256 || registryRow?.contentSha256;
  if (!registryRow || (actualSha && actualSha !== expectedSha)) {
    shaMismatches.push({ artifact_id: id, expected_sha256: expectedSha, actual_sha256: actualSha || null });
  }
}
const blockers = [...j.blockers];
if (shaMismatches.length) blockers.push('SHA_MISMATCH');
return [{
  json: {
    ...j,
    sha_mismatches: shaMismatches,
    sha_check_status: shaMismatches.length ? 'MISMATCH' : 'MATCHED',
    blockers: Array.from(new Set(blockers))
  }
}];

const j = $input.first().json;
const registryResults = Array.isArray(j.registry_results) ? j.registry_results : [];
const unsafeStatuses = ['SHADOW', 'SUPERSEDED', 'REVOKED', 'REFERENCE_ONLY'];
const statusViolations = registryResults.filter((row) => {
  const status = String(row.status || row.artifact_status || '').toUpperCase();
  const isActive = row.is_active === true || row.active === true || row.loaded_as_active === true;
  return unsafeStatuses.includes(status) && isActive;
});
const blockers = [...j.blockers];
if (statusViolations.length) blockers.push('STATUS_NOT_SAFE');
return [{
  json: {
    ...j,
    status_violations: statusViolations,
    status_safety: statusViolations.length ? 'BLOCKED' : 'SAFE',
    blockers: Array.from(new Set(blockers))
  }
}];

const j = $input.first().json;
const checklist = Array.isArray(j.validation_checklist) ? j.validation_checklist : [];
const requiredChecklistItems = ['manifest_parsed', 'dependency_map_parsed', 'registry_resolved', 'sha_match_verified', 'status_safe'];
const completedItems = checklist.filter((item) => item?.passed === true || item?.status === 'PASS').map((item) => item?.key || item?.name || item?.item).filter(Boolean);
const missingChecklistItems = requiredChecklistItems.filter((item) => !completedItems.includes(item));
const blockers = [...j.blockers];
if (!checklist.length) blockers.push('CHECKLIST_MISSING');
if (missingChecklistItems.length) blockers.push(`CHECKLIST_INCOMPLETE:${missingChecklistItems.join(',')}`);
return [{
  json: {
    ...j,
    validation_checklist: checklist,
    missing_checklist_items: missingChecklistItems,
    checklist_status: missingChecklistItems.length ? 'INCOMPLETE' : 'COMPLETE',
    blockers: Array.from(new Set(blockers))
  }
}];

const j = $input.first().json;
const blockers = Array.from(new Set(j.blockers || []));
const invalidBlockers = blockers.filter((item) => item.startsWith('MISSING_') || item.endsWith('_MISSING') || item.includes('PARSE_FAILED'));
const blockedBlockers = blockers.filter((item) => ['REGISTRY_LOOKUP_REQUIRED', 'UNRESOLVED_ARTIFACTS', 'SHA_MISMATCH', 'STATUS_NOT_SAFE'].includes(item));
const reviewBlockers = blockers.filter((item) => item.startsWith('CHECKLIST_INCOMPLETE'));
let packageStatus = 'PACKAGE_VALID';
if (invalidBlockers.length) {
  packageStatus = 'PACKAGE_INVALID';
} else if (blockedBlockers.length) {
  packageStatus = 'PACKAGE_BLOCKED';
} else if (reviewBlockers.length) {
  packageStatus = 'PACKAGE_NEEDS_REVIEW';
}
const nextActions = packageStatus === 'PACKAGE_VALID'
  ? ['Proceed to release gate review']
  : packageStatus === 'PACKAGE_BLOCKED'
    ? ['Return package to registry owner', 'Fix SHA/status mismatches', 'Re-run validator']
    : packageStatus === 'PACKAGE_NEEDS_REVIEW'
      ? ['Send to human review', 'Confirm checklist completion', 'Re-run validator']
      : ['Fix manifest/dependency structure', 'Rebuild package metadata', 'Re-run validator'];
return [{
  json: {
    package_id: j.package_id,
    package_path: j.package_path,
    release_type: j.release_type,
    package_status: packageStatus,
    required_files: j.required_files,
    missing_files: j.missing_files,
    manifest_status: j.manifest_status,
    dependency_map_status: j.dependency_map_status,
    registry_resolution_status: j.registry_resolution_status,
    sha_check_status: j.sha_check_status,
    status_safety: j.status_safety,
    checklist_status: j.checklist_status,
    blockers,
    unresolved_artifacts: j.unresolved_artifacts,
    sha_mismatches: j.sha_mismatches,
    status_violations: j.status_violations,
    missing_checklist_items: j.missing_checklist_items,
    next_actions: nextActions,
    approval_required: packageStatus !== 'PACKAGE_VALID'
  }
}];

const j = $json;
const body = j.body?.payload || j;
return {
  ...j,
  audit_write_mode: 'LIVE_DB',
  log_action: body.action || 'system_event'
};
